/** Owner-only manual quotation evidence and the existing Phase5 authorizer. */
import {decimal,times} from './model.ts';
type RPC=(path:string,body?:unknown,timeout?:number)=>Promise<any>;
type Context={api:RPC;owner:()=>number;canAuthorize:()=>boolean;ready:()=>Promise<void>;notify:(message:string,error?:boolean)=>void;authorized:(result:any)=>Promise<void>};
const esc=(v:unknown)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const el=<T extends HTMLElement=HTMLElement>(id:string)=>document.querySelector<T>('#'+id)!;
const labels:Record<string,string>={OPEN:'Awaiting owner review',CANCELED:'Request canceled',COMMITTED:'Purchase order authorized',FULL:'Fully available',PARTIAL:'Partially available',UNAVAILABLE:'Unavailable',MISSING:'Vendor has not answered',EXCESS:'More than requested',ACCEPT_QUOTE:'Accept vendor price',REJECT:'Reject price',UNRESOLVED:'Review unresolved quotation',OWNER_EXCEPTION:'Explicit owner valuation exception'};
function priceFinding(line:any,report:any){if(line.expected_unit_cost===null||report.quoted_pack_price===null)return 'Expected or quoted cost unknown';const a=decimal(report.quoted_pack_price),b=times(decimal(line.expected_unit_cost),BigInt(line.pack_size));return a.n*10n**BigInt(b.scale)===b.n*10n**BigInt(a.scale)?'Exact price match':'Price discrepancy';}
export class QuotationWorkflow{
 private dialog:HTMLDialogElement;private d:any;private id='';private page=0;private choices:Record<string,any>={};private components:Record<string,any>={};private incremental='';private contract=false;private units=false;private release=false;private review:any;private busy=false;private reissues:Record<string,any>={};private reissueReason='';private readOnly=false;
 constructor(private ctx:Context){this.dialog=document.createElement('dialog');this.dialog.id='quotation-dialog';this.dialog.className='submission-dialog quotation-dialog';document.body.append(this.dialog);this.dialog.addEventListener('cancel',event=>{if(this.busy)event.preventDefault();});}
 private url(suffix=''){return '/api/quotation-requests/'+this.id+suffix;}
 private open(title:string,body:string,action?:()=>Promise<void>,label='Continue'){
  if(this.dialog.open)this.dialog.close();this.dialog.innerHTML=`<form method="dialog"><div class="dialog-heading"><h2>${esc(title)}</h2><button value="cancel" class="close" aria-label="Close quotation review">×</button></div><div class="dialog-body">${body}</div><p id="quotation-error" role="alert"></p><div class="dialog-footer"><button value="cancel">Close</button>${action?`<button type="button" id="quotation-next" class="primary">${esc(label)}</button>`:''}</div></form>`;this.dialog.showModal();if(this.busy)this.lock();if(action)el('quotation-next').onclick=()=>void this.run(action);
 }
 private lock(){this.dialog.setAttribute('aria-busy','true');this.dialog.querySelectorAll<HTMLInputElement|HTMLButtonElement|HTMLSelectElement|HTMLTextAreaElement>('button,input,select,textarea').forEach(control=>{if(!control.disabled){control.dataset.quoteOperation='true';control.disabled=true;}});}
 private async run(action:()=>Promise<void>){if(this.busy)return;this.busy=true;this.lock();try{await action();}catch(error){el('quotation-error').textContent=(error as Error).message;}finally{this.busy=false;this.dialog.removeAttribute('aria-busy');this.dialog.querySelectorAll<HTMLInputElement|HTMLButtonElement|HTMLSelectElement|HTMLTextAreaElement>('[data-quote-operation]').forEach(control=>{control.disabled=false;delete control.dataset.quoteOperation;});}}
 private pager(total:number){return `<div class="submission-pagination"><button type="button" id="quote-prev" ${this.page===0?'disabled':''}>Previous 100</button><span>Viewing ${this.page*100+1}–${Math.min(this.page*100+100,total)} of ${total}</span><button type="button" id="quote-more" ${this.page*100+100>=total?'disabled':''}>Next 100</button></div>`;}
 private pageButtons(render:()=>void,capture=()=>{}){el('quote-prev').onclick=()=>{capture();this.page--;render();};el('quote-more').onclick=()=>{capture();this.page++;render();};}
 async openRequest(id:string){await this.ctx.ready();this.id=id;if(this.ctx.canAuthorize())await this.ctx.api(this.url('/prepare'),{command_id:crypto.randomUUID()});await this.load();}
 async list(){await this.ctx.ready();const rows=await this.ctx.api('/api/quotation-requests');this.open('Vendor quotation requests',`<p>Uploads are evidence. Select a response explicitly, review all quantities and prices, then authorize purchasing separately.</p><div class="quote-request-list">${rows.length?rows.map((r:any)=>`<button type="button" data-request="${r.id}"><b>${esc(r.supplier_name)}</b><span>${esc(r.state?labels[r.state]:'Prepare quotation workbook')}</span><small>${esc(r.id)} · ${esc(r.created_at.slice(0,10))}</small></button>`).join(''):'No confirmation requests. Prepare selected vendors in the worksheet first.'}</div>`);this.dialog.querySelectorAll<HTMLButtonElement>('[data-request]').forEach(b=>b.onclick=()=>void this.run(async()=>{this.id=b.dataset.request!;if(!rows.find((r:any)=>r.id===this.id).state){if(!this.ctx.canAuthorize())throw Error('Quotation decisions are paused.');await this.ctx.api(this.url('/prepare'),{command_id:crypto.randomUUID()});}await this.load();}));}
 private async load(){this.d=await this.ctx.api(this.url());this.page=0;this.choices={};this.components={};this.incremental='';this.contract=this.units=this.release=false;this.overview();}
 private overview(){const d=this.d,h=d.head,can=this.ctx.canAuthorize()&&h.state==='OPEN';this.open('Quotation · '+d.snapshot.supplier.name,`<div class="submission-summary"><b>${esc(labels[h.state])}</b><span>Request revision ${d.revision_number} · ${d.snapshot.lines.length} lines</span><span>${h.selected_response_id?'Response explicitly selected':'No active response selected'}</span></div><div class="quote-actions">${d.committed_result?`<button type="button" id="quote-open-commitment">View authorized PO #${d.committed_result.children[0].purchase_order_id}</button>`:''}<a href="${this.url('/workbooks/'+h.revision_id)}" download>Download vendor quotation workbook</a>${can?'<label>Upload completed XLSX<input id="quote-upload" type="file" accept=".xlsx"></label><button type="button" id="quote-reissue">Request revised quotation</button><button type="button" id="quote-cancel">Cancel pending request</button>':''}</div><h3>Latest retained responses and selected response</h3><table class="quote-table"><thead><tr><th>Received</th><th>Response identity</th><th>Revision / findings</th><th>Owner selection</th></tr></thead><tbody>${d.responses.map((r:any)=>`<tr><td>${esc(r.created_at)}</td><td>${esc(r.id)}</td><td>${r.revision_id===h.revision_id?'Current request':'Outdated request'}<small>${esc(r.issue_count?(r.payload.issues.join(' · ')||r.issue_count+' unanswered vendor fields'):'All vendor fields answered')}</small></td><td>${r.id===h.selected_response_id?'Selected by owner':can&&r.revision_id===h.revision_id?`<button type="button" data-response="${r.id}">Select this response</button>`:'Historical evidence retained'}</td></tr>`).join('')}</tbody></table><div class="quote-actions"><button type="button" id="quote-owner-history">View immutable owner review history</button></div><h3>Original uploads and validation</h3><div class="quote-evidence">${d.uploads.map((u:any)=>`<p><a href="${this.url('/uploads/'+u.id)}" download>${esc(u.filename)}</a> · ${u.validation.valid?(u.validation.stale?'Historical evidence':'Valid quotation evidence'):'Quarantined'}${u.validation.errors.length?' · '+esc(u.validation.errors.join(' · ')):''}<small>SHA-256 ${esc(u.sha256)}</small></p>`).join('')||'No vendor response uploaded.'}</div><details><summary>Request revisions, owner decisions and authorization history</summary>${d.owner_reviews.map((r:any)=>`<p>${esc(r.created_at)} · request revision ${r.request_revision} · ${r.blocking.length?"Owner review needs attention: "+esc(r.blocking.join(" · ")):"Exact owner review prepared: "+esc(r.committed_total)+" USD"} · response ${esc(r.response_id)}</p>`).join("")}${d.revisions.map((r:any)=>`<p><a href="${this.url('/workbooks/'+r.id)}" download>Original workbook revision ${r.number}</a> · ${esc(r.sha256)}</p>`).join('')}${d.history.map((r:any)=>`<p>${esc(r.created_at)} · ${esc(r.reason)} · owner ${r.owner_id}</p>`).join('')}</details>`,can&&h.selected_response_id?async()=>this.edit():undefined,'Compare quantities and prices');
  this.dialog.querySelectorAll<HTMLButtonElement>('[data-response]').forEach(b=>b.onclick=()=>void this.run(async()=>{await this.ctx.api(this.url('/decisions'),{command_id:crypto.randomUUID(),expected_version:h.version,kind:'SELECT_RESPONSE',reason:'Owner explicitly selects this retained response for review',response_id:b.dataset.response});await this.load();}));
  el<HTMLInputElement>('quote-upload')?.addEventListener('change',()=>void this.run(async()=>{const file=el<HTMLInputElement>('quote-upload').files?.[0];if(!file)return;if(file.size>10*1024*1024)throw Error('Upload at most 10 MiB.');const csrf=decodeURIComponent(document.cookie.split('; ').find(s=>s.startsWith('csrf_token='))?.split('=').slice(1).join('=')??'');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),120000);let r:Response;try{r=await fetch(this.url('/uploads?filename='+encodeURIComponent(file.name)),{method:'POST',body:file,credentials:'same-origin',headers:{'X-CSRF-Token':csrf,'Content-Type':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'},signal:controller.signal});}finally{clearTimeout(timer);}const result=await r.json();if(!r.ok)throw Error(result.detail??'Upload was rejected');await this.load();if(!result.validation.valid)el('quotation-error').textContent='Workbook quarantined: '+result.validation.errors.join(' · ');else this.ctx.notify(result.duplicate_upload?'Existing upload recovered; no duplicate response.':'Response evidence saved. Choose the active response explicitly.');}));el('quote-open-commitment')?.addEventListener('click',()=>void this.run(async()=>{this.dialog.close();await this.ctx.authorized(d.committed_result);}));el('quote-owner-history').onclick=()=>this.history();el('quote-reissue')?.addEventListener('click',()=>{this.reissues=Object.fromEntries(d.snapshot.lines.map((l:any)=>[l.row_id,{pack_size:l.pack_size,packs:[...l.packs]}]));this.page=0;this.reissueReason='';this.reissue();});el('quote-cancel')?.addEventListener('click',()=>this.cancel());
 }
 private reports():Map<string,any>{return new Map(this.d.responses.find((r:any)=>r.id===this.d.head.selected_response_id).payload.lines.map((r:any)=>[r.line_id,r]));}
 private edit(){this.readOnly=false;const d=this.d,reports=this.reports(),response=d.responses.find((r:any)=>r.id===d.head.selected_response_id).payload,lines=d.snapshot.lines.slice(this.page*100,this.page*100+100);this.open('Compare vendor quantities and prices',`<div class="submission-summary"><b>${esc(d.snapshot.supplier.name)} · revision ${d.revision_number}</b><span>${d.snapshot.lines.length} lines · orders are whole packs</span></div><div class="quote-actions"><button type="button" id="quote-copy">Copy requested allocations for the entire request</button><button type="button" id="quote-accept">Accept quoted prices on this page</button><button type="button" id="quote-charges">Use vendor-reported charges</button></div><div class="submission-lines"><table class="quote-table"><thead><tr><th>Product / variation</th><th>Units / pack</th><th>Requested packs</th><th>Vendor packs</th><th>Quantity finding</th><th>Expected unit cost</th><th>Quoted pack price USD / comparison</th><th>Price action</th>${d.snapshot.stores.map((s:any)=>`<th title="${esc(s.name)}">${esc(s.name)} approved packs</th>`).join('')}<th>Exception pack price / reason</th><th>Quantity exception / excess reason</th></tr></thead><tbody>${lines.map((l:any)=>{const r=reports.get(l.row_id),v=this.choices[l.row_id]??{},finding=priceFinding(l,r);return `<tr data-quote-line="${l.row_id}" class="${r.status!=='FULL'||finding!=='Exact price match'?'quote-discrepancy':''}"><td><b>${esc(l.name)}</b><br>${esc(l.variation)}<small>${esc(l.sku)}</small></td><td>${l.pack_size}</td><td>${l.total_packs}</td><td>${r.available_packs??'Unanswered'}</td><td>${esc(labels[r.status])}</td><td>${esc(l.expected_unit_cost??'Unknown')}</td><td>${esc(r.quoted_pack_price??'Missing')}<small>${esc(finding)} · unit equivalent ${r.quoted_pack_price??'unknown'} / ${l.pack_size}</small></td><td><select data-action="${l.row_id}"><option value="">Choose explicitly</option>${['ACCEPT_QUOTE','REJECT','UNRESOLVED','OWNER_EXCEPTION'].map(k=>`<option value="${k}" ${v.price_action===k?'selected':''}>${esc(labels[k])}</option>`).join('')}</select></td>${[0,1,2,3].map(i=>`<td><input data-packs="${l.row_id}" data-store="${i}" inputmode="numeric" value="${v.packs?.[i]??''}" aria-label="${esc(d.snapshot.stores[i].name)} approved packs"></td>`).join('')}<td><input data-price="${l.row_id}" inputmode="decimal" value="${esc(v.pack_price??'')}" placeholder="Exception pack price"><input data-reason="${l.row_id}" value="${esc(v.reason??'')}" maxlength="2000" placeholder="Explicit valuation reason"></td><td><input data-quantity="${l.row_id}" value="${esc(v.quantity_reason??'')}" maxlength="2000" placeholder="Unconfirmed availability reason"><input data-excess="${l.row_id}" value="${esc(v.excess_reason??'')}" maxlength="2000" placeholder="Explicit excess authorization reason"></td></tr>`;}).join('')}</tbody></table></div>${this.pager(d.snapshot.lines.length)}<div class="quote-components">${['freight','tax','discount'].map(k=>{const v=this.components[k]??{};return `<label>${k} USD · vendor ${esc(response.components[k]??'Unanswered')}<select data-charge-source="${k}"><option value="">Choose explicitly</option><option value="VENDOR_QUOTE" ${v.source==='VENDOR_QUOTE'?'selected':''}>Accept vendor amount</option><option value="OWNER_EXCEPTION" ${v.source==='OWNER_EXCEPTION'?'selected':''}>Explicit owner exception</option></select><input data-charge-amount="${k}" value="${esc(v.amount??'')}" inputmode="decimal" placeholder="Approved exception amount"><input data-charge-reason="${k}" value="${esc(v.reason??'')}" maxlength="2000" placeholder="Exception reason"></label>`;}).join('')}</div><label class="incremental-label">Review other incoming supply / pending requests; explain additional purchasing<textarea id="quote-incremental" maxlength="2000">${esc(this.incremental)}</textarea></label><label class="authorization-ack"><input type="checkbox" id="quote-contract" ${this.contract?'checked':''}> I approve this financial candidate for this review only: ${esc(d.financial_description)}.</label><label class="authorization-ack"><input type="checkbox" id="quote-units" ${this.units?'checked':''}> I explicitly approve the four-decimal legacy unit representation; exact pack totals and representation differences remain recorded.</label><label class="authorization-ack"><input type="checkbox" id="quote-release" ${this.release?'checked':''}> This is the final request resolution. Release unfilled remainder from pending requests; further purchasing requires a new reviewed decision.</label>`,async()=>{this.capture(true);this.review=await this.ctx.api(this.url('/reviews'),{review_id:crypto.randomUUID(),expected_version:d.head.version,response_id:d.head.selected_response_id,choices:this.choices,components:this.components,contract:this.contract?d.financial_contract:null,unit_adapter_approved:this.units,release_remainder:this.release,incremental_reason:this.incremental},120000);if(this.review.blocking.length){this.edit();el('quotation-error').textContent=this.review.blocking.slice(0,16).join(' · ');}else{this.page=0;this.confirm();}},'Review exact final purchasing authorization');
 this.pageButtons(()=>this.edit(),()=>this.capture(false));el('quote-copy').onclick=()=>{this.capture(false);for(const l of d.snapshot.lines)this.choices[l.row_id]={...(this.choices[l.row_id]??{}),packs:[...l.packs]};this.edit();};el('quote-accept').onclick=()=>{this.capture(false);for(const l of lines)if(reports.get(l.row_id).quoted_pack_price!==null)this.choices[l.row_id]={...(this.choices[l.row_id]??{}),price_action:'ACCEPT_QUOTE',reason:'Owner explicitly accepts this vendor quotation'};this.edit();};el('quote-charges').onclick=()=>{this.capture(false);for(const k of ['freight','tax','discount'])this.components[k]={source:'VENDOR_QUOTE',amount:null,reason:'Owner explicitly accepts reported amount'};this.edit();};
 }
 private capture(strict:boolean){for(const row of this.dialog.querySelectorAll<HTMLElement>('[data-quote-line]')){const id=row.dataset.quoteLine!,read=(selector:string)=>row.querySelector<HTMLInputElement|HTMLSelectElement>(selector)!.value,packs=[...row.querySelectorAll<HTMLInputElement>('[data-packs]')].map(i=>{if(!/^\d+$/.test(i.value)){if(strict)throw Error('Enter all four approved whole-pack allocations explicitly.');return null;}const n=Number(i.value);if(!Number.isSafeInteger(n)||n>1000000)throw Error('Approved packs must fit 0–1,000,000 per store.');return n;});this.choices[id]={packs,price_action:read('[data-action]'),pack_price:read('[data-price]')||null,reason:read('[data-reason]'),quantity_reason:read('[data-quantity]'),excess_reason:read('[data-excess]')};}for(const k of ['freight','tax','discount'])this.components[k]={source:this.dialog.querySelector<HTMLSelectElement>(`[data-charge-source="${k}"]`)!.value,amount:this.dialog.querySelector<HTMLInputElement>(`[data-charge-amount="${k}"]`)!.value||null,reason:this.dialog.querySelector<HTMLInputElement>(`[data-charge-reason="${k}"]`)!.value};this.incremental=el<HTMLTextAreaElement>('quote-incremental').value;this.contract=el<HTMLInputElement>('quote-contract').checked;this.units=el<HTMLInputElement>('quote-units').checked;this.release=el<HTMLInputElement>('quote-release').checked;}
 private confirm(){const r=this.review,q=r.quotation,f=q.financial,lines=r.lines.slice(this.page*100,this.page*100+100);this.open(this.readOnly?'Original owner quotation review':'Authorize exact reviewed quotation',`<div class="submission-summary"><b>${esc(r.groups[0].profile.name)} · request revision ${q.revision_number}</b><span>Selected response ${esc(q.response_id)}</span><span>${r.lines.length} reviewed lines · USD</span></div><div class="exact-total"><b>${f.total===null?'Unresolved financial total':'Approved commitment '+esc(f.total)+' USD'}</b><span>${f.complete?'Merchandise':'Known merchandise subtotal'} ${esc(f.merchandise)} + freight ${esc(f.freight)} + tax ${esc(f.tax)} − discount ${esc(f.discount)}</span></div><p>${esc(f.description)}</p>${r.blocking?.length?`<p class="quote-discrepancy">${esc(r.blocking.join(" · "))}</p>`:''}${r.configuration_warnings.length?`<p class="quote-discrepancy">${esc(r.configuration_warnings.join(" · "))}</p>`:""}<p>Other incoming / pending requests reviewed: ${esc(r.incremental_reason)}</p><div class="submission-lines"><table class="quote-table"><thead><tr><th>Product / variation</th><th>Requested / vendor packs</th><th>Approved store packs</th><th>Expected unit cost</th><th>Vendor pack price</th><th>Owner valuation / comparison</th><th>Legacy unit representation</th><th>Line total USD</th><th>Current incoming units</th></tr></thead><tbody>${lines.map((l:any)=>`<tr class="${l.price_comparison==='EQUAL'&&l.reported.status==='FULL'?'':'quote-discrepancy'}"><td>${esc(l.name)}<br>${esc(l.variation)}</td><td>${l.requested_total_packs} / ${l.reported.available_packs??'Unanswered'}<small>${esc(labels[l.reported.status])}</small></td><td>${l.packs.join(' / ')}<small>${l.total_units} individual units</small></td><td>${esc(l.expected_unit_cost??'Unknown')}</td><td>${esc(l.reported.quoted_pack_price??'Missing')}</td><td>${esc(labels[l.quote_decision])}<small>${l.price_comparison==='EQUAL'?'Exact price match':l.price_comparison==='UNKNOWN'?'Comparison unresolved; explicitly reviewed':'Price discrepancy; explicitly reviewed'}</small>${esc(l.owner_reason)}</td><td>${esc(l.valuation?.unit_value??(l.total_packs?'Unresolved valuation':'No purchase'))}<small>Representation difference ${esc(l.unit_adapter_delta??'—')}</small></td><td>${esc(l.line_total??(l.total_packs?'Unresolved total':'No purchase'))}</td><td>${r.supply.incoming[l.variation_id].join(' / ')}<details><summary>Supply / requests</summary>${r.supply.overlap[l.variation_id].map((v:any)=>`<p>${esc(v.kind.replaceAll('_',' ').toLowerCase())} · ${esc(v.reference)} · ${v.units??'unknown'} units</p>`).join('')}</details></td></tr>`).join('')}</tbody></table></div>${this.pager(r.lines.length)}<p class="muted">Store order ${r.stores.map((s:any)=>esc(s.name)).join(' / ')}. Original requests, quotations and expected costs remain preserved. Unfilled remainder will be released by final authorization.</p><button type="button" id="quote-back">Back to owner decisions</button>${this.readOnly?'<p>This immutable historical review provides no new purchasing authority.</p>':'<label class="authorization-ack"><input type="checkbox" id="quote-final-ack"> I authorize exactly these quantities, allocations, valuations, financial components, excess/exception decisions and release of the unfilled request remainder.</label>'}`,this.readOnly?undefined:async()=>{if(!el<HTMLInputElement>('quote-final-ack').checked)throw Error('Explicit final owner authorization is required.');const prefix='v5-authorization:'+this.ctx.owner()+':',prior=Object.keys(localStorage).filter(k=>k.startsWith(prefix)).map(k=>JSON.parse(localStorage.getItem(k)!)).find(v=>v.review_id===r.id),intent=prior??{command_id:crypto.randomUUID(),review_id:r.id,acknowledged:true};localStorage.setItem(prefix+intent.command_id,JSON.stringify(intent));let result;try{result=await this.ctx.api('/api/purchase-authorizations',intent,120000);}catch(error){try{result=await this.ctx.api('/api/authorization-commands/'+intent.command_id);}catch(lookup){if([409,422].includes((error as Error&{status?:number}).status??0)&&(lookup as Error&{status?:number}).status===404)localStorage.removeItem(prefix+intent.command_id);throw error;}}localStorage.removeItem(prefix+intent.command_id);this.dialog.close();await this.ctx.authorized(result);},'Authorize final purchase order');this.pageButtons(()=>this.confirm());el('quote-back').textContent=this.readOnly?'Back to response history':'Back to owner decisions';el('quote-back').onclick=()=>{this.page=0;if(this.readOnly)this.overview();else this.edit();};}
 private history(){const rows=this.d.owner_reviews;this.open('Immutable owner review history',`<p>Original owner decisions and financial reviews remain preserved. Viewing a historical review creates no purchasing authority.</p><div class="quote-request-list">${rows.map((r:any)=>`<button type="button" data-owner-review="${r.id}">${esc(r.created_at)} · revision ${r.request_revision} · ${r.blocking.length?'Needs owner review':esc(r.committed_total)+' USD'}</button>`).join('')||'No owner quotation review recorded yet.'}</div>`);this.dialog.querySelectorAll<HTMLButtonElement>('[data-owner-review]').forEach(b=>b.onclick=()=>void this.run(async()=>{this.review=await this.ctx.api(this.url('/reviews/'+b.dataset.ownerReview));this.readOnly=true;this.page=0;this.confirm();}));}
 private cancel(){this.open('Cancel pending purchasing request',`<p>Canceling releases only this pending request reservation. Original requests and replies remain in history. Issued POs require a separate amendment workflow.</p><label>Owner reason<textarea id="quote-cancel-reason" maxlength="2000"></textarea></label><label class="authorization-ack"><input type="checkbox" id="quote-cancel-ack"> I explicitly cancel this pending request and release its reservation.</label>`,async()=>{if(!el<HTMLInputElement>('quote-cancel-ack').checked)throw Error('Explicit cancellation acknowledgment required.');await this.ctx.api(this.url('/decisions'),{command_id:crypto.randomUUID(),expected_version:this.d.head.version,kind:'CANCEL',reason:el<HTMLTextAreaElement>('quote-cancel-reason').value});await this.load();},'Cancel pending request');}
 private reissue(){const d=this.d,lines=d.snapshot.lines.slice(this.page*100,this.page*100+100);this.open('Request revised quotation',`<p>Review the exact pack configuration and store quantities for the new request revision. Previous workbooks and responses remain historical; no active response is selected automatically.</p><div class="submission-lines"><table class="quote-table"><thead><tr><th>Product / variation</th><th>Units per pack</th>${d.snapshot.stores.map((s:any)=>`<th>${esc(s.name)} requested packs</th>`).join('')}</tr></thead><tbody>${lines.map((l:any)=>{const v=this.reissues[l.row_id];return `<tr data-reissue="${l.row_id}"><td>${esc(l.name)}<br>${esc(l.variation)}</td><td><input data-size value="${v.pack_size}" inputmode="numeric"></td>${v.packs.map((n:number)=>`<td><input data-new-pack value="${n}" inputmode="numeric"></td>`).join('')}</tr>`;}).join('')}</tbody></table></div>${this.pager(d.snapshot.lines.length)}<label>Owner reason<textarea id="quote-reissue-reason" maxlength="2000">${esc(this.reissueReason)}</textarea></label><label class="authorization-ack"><input type="checkbox" id="quote-reissue-ack"> I approve the complete reissued request. Unedited lines retain their shown request allocations.</label>`,async()=>{capture();if(!el<HTMLInputElement>('quote-reissue-ack').checked)throw Error('Explicit reissue approval required.');await this.ctx.api(this.url('/decisions'),{command_id:crypto.randomUUID(),expected_version:d.head.version,kind:'REISSUE',reason:this.reissueReason,changes:this.reissues},120000);await this.load();},'Reissue reviewed request');const capture=()=>{this.reissueReason=el<HTMLTextAreaElement>('quote-reissue-reason').value;for(const row of this.dialog.querySelectorAll<HTMLElement>('[data-reissue]')){const size=row.querySelector<HTMLInputElement>('[data-size]')!.value,packs=[...row.querySelectorAll<HTMLInputElement>('[data-new-pack]')].map(v=>v.value);if(!/^[1-9]\d*$/.test(size)||packs.some(v=>!/^\d+$/.test(v)))throw Error('Explicit whole pack size and four quantities required.');this.reissues[row.dataset.reissue!]={pack_size:Number(size),packs:packs.map(Number)};}};this.pageButtons(()=>this.reissue(),capture);}
}
