const esc=(v:unknown)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
export class EmailAttention{
 private dialog=document.createElement('dialog');
 constructor(private api:(p:string,b?:unknown,t?:number)=>Promise<any>){this.dialog.className='email-dialog';document.body.append(this.dialog);}
 async open(){const data=await this.api('/api/purchasing-email');this.dialog.innerHTML=`<form method="dialog"><h2>Purchasing email · Needs Attention</h2><p>Owner monitors exceptions. Correspondence is retained indefinitely. Provider acceptance is separate from delivery; vendor replies require owner review.</p>${!data.enabled?'<p>Automated email is paused. Manual delivery and workbook upload remain available.</p>':''}${!data.provider_configured?'<p>No isolated provider is configured. Original documents remain available in Purchases and Vendor quotes.</p>':''}<h3>Outbound delivery</h3><table><thead><tr><th>Document</th><th>Vendor recipient</th><th>Status</th><th>Action / evidence</th></tr></thead><tbody>${data.deliveries.map((d:any)=>`<tr><td>${esc(d.envelope.subject)}</td><td>${esc(d.envelope.recipient||'Missing vendor email')}</td><td>${esc(({NOT_SENT:'Not sent',SENDING:'Sending',ACCEPTED:'Accepted by provider',DELIVERED:'Delivered to recipient server',FAILED:'Failed · eligible for owner retry',UNCERTAIN:'Delivery outcome uncertain',HELD:'Needs attention · held'} as any)[d.state])}</td><td>${esc(d.evidence.detail||d.evidence.meaning||'')} ${data.enabled&&data.provider_configured&&['FAILED','UNCERTAIN','SENDING'].includes(d.state)?`<button type="button" data-mail-retry="${d.id}" data-interrupted="${d.state==='SENDING'}">${d.state==='FAILED'?'Review retry':'Review uncertain outcome'}</button>`:''}${d.state!=='DELIVERED'?`<button type="button" data-manual-handoff="${d.id}" data-interrupted="${d.state==='SENDING'}">Record manual handoff / hold automatic delivery</button>`:''}<small>${esc(d.provider_id||'')}</small></td></tr>`).join('')||'<tr><td colspan="4">No automatic deliveries recorded. Vendor opt-in settings control automatic delivery.</td></tr>'}</tbody></table><h3>Vendor replies and imports</h3>${data.imports.map((i:any)=>`<p><a href="/api/purchasing-email/attachments/${encodeURIComponent(i.attachment_id)}">${esc(i.filename)}</a> · <strong>${esc(i.result.outcome.replaceAll('_',' '))}</strong> · ${esc(i.result.detail||'')}${i.request_id?' · Review in Vendor quotes':''}${i.result.imported?.validation?.issues?.length?' · '+esc(JSON.stringify(i.result.imported.validation.issues)):''}</p>`).join('')||'<p>No returned attachments recorded.</p>'}<h3>Inbound processing</h3>${data.events.map((e:any)=>`<p>${esc(e.type)} · ${esc(e.state)} · ${esc(e.evidence.outcome||'')}${data.enabled&&data.provider_configured&&['FAILED','PROCESSING'].includes(e.state)?` <button type="button" data-event-retry="${esc(e.id)}" data-interrupted="${e.state==='PROCESSING'}">Review processing recovery</button>`:''}</p>`).join('')||'<p>No inbound events recorded.</p>'}<p>Download documents in Purchases or Vendor quotes. Manually upload returned workbooks in Vendor quotes. An email or reply never authorizes another PO.</p><p id="email-error" role="alert"></p><footer><button type="button" id="email-refresh">Refresh</button><button>Close</button></footer></form>`;if(!this.dialog.open)this.dialog.showModal();this.dialog.querySelector<HTMLButtonElement>('#email-refresh')!.onclick=()=>void this.run(()=>this.open());this.dialog.querySelectorAll<HTMLButtonElement>('[data-manual-handoff]').forEach(b=>b.onclick=()=>void this.run(async()=>{const reason=prompt('Describe the manual document handoff. Automatic delivery will remain held; this does not claim a provider delivered the original email.');if(!reason)return;const interrupted=b.dataset.interrupted==='true';if(interrupted&&!confirm('Confirm the previous sending worker has stopped. Its earlier provider outcome may remain uncertain.'))return;await this.api('/api/purchasing-email/deliveries/'+b.dataset.manualHandoff+'/manual',{command_id:crypto.randomUUID(),reason,interrupted_worker_confirmed:interrupted});await this.open();}));this.dialog.querySelectorAll<HTMLButtonElement>('[data-mail-retry],[data-event-retry]').forEach(b=>b.onclick=()=>void this.run(async()=>{const reason=prompt('Describe the owner review. Uncertain deliveries will not be resent.');if(!reason)return;if(b.dataset.mailRetry&&b.textContent?.includes('uncertain')){const providerId=prompt('If you have the original Resend message ID, enter it for verified reconciliation. Leave blank to retain uncertainty without resending.');if(providerId){await this.api('/api/purchasing-email/deliveries/'+b.dataset.mailRetry+'/reconcile',{reason,provider_id:providerId},120000);await this.open();return;}}const interrupted=b.dataset.interrupted==='true';if(interrupted&&!confirm('Confirm the previous worker has stopped. The original operation identity will be retained.'))return;const url=b.dataset.mailRetry?'/api/purchasing-email/deliveries/'+b.dataset.mailRetry+'/retry':'/api/purchasing-email/events/'+encodeURIComponent(b.dataset.eventRetry!)+'/retry';await this.api(url,{reason,interrupted_worker_confirmed:interrupted},120000);await this.open();}));}
 private async run(task:()=>Promise<void>){try{await task();}catch(e){this.dialog.querySelector('#email-error')!.textContent=(e as Error).message;}}
}
